'use strict';

class Router {
  constructor(routes) {
    this.routes = routes;
  }

  parse(path) {
    return { params: path.split('/').filter(Boolean) };
  }

  match(path) {
    const { params, ...rest } = this.parse(path);
      ...rest
    return params;
  }
}

module.exports = Router;

'use strict';

const Router = require('../lib/router');

test('matches segments', () => {
  expect(new Router([]).match('/a/b')).toEqual(['a', 'b']);
});
